    if (Array.isArray(entry)) {
      return entry.some(function (e) {
        return entryHasScope(e);
      });
    }
    if (!entry || !entry.scopeType) return false;
    if (entry.scopeType === "role" && entry.roles && entry.roles.length > 0) return true;
