    function executeTipAllocationScope(scope) {
      invalidateDayPipelineCache();
      var dates = buildDateRange(scope.startDate, scope.endDate);
      var statusByDate = Object.create(null);
      buildDailyDataset(getStoreEmployees()).forEach(function(row) { statusByDate[row.dateKey] = row.businessStatusResult; });
      var skippedClosedCount = 0;
      var skippedPaidCount = 0;
      dates = dates.filter(function(dateKey) {
        var result = statusByDate[dateKey];
        var allowed = result && result.allocatable;
        if (!allowed) skippedClosedCount += 1;
        if (allowed && window.TipOutDateState && TipOutDateState.inspect(scope.store, dateKey).locked) {
          skippedPaidCount += 1;
          allowed = false;
        }
        return allowed;
      });
      if (!dates.length) {
        var closedError = new Error(skippedPaidCount ? '所选日期均已发放或不可修改，未执行分配' : '所选日期均未营业，无法进行小费分配');
        closedError.allocationStage = 'eligibility';
        throw closedError;
      }
      var allocatedDates = getAllocatedDatesForStore(scope.store);
      dates.forEach(function(k) { allocatedDates.add(k); });
      try {
        saveAllocatedDatesForStore(scope.store, allocatedDates);
      } catch (error) {
        error.allocationStage = 'write';
        throw error;
      }
      try {
        if (window.TipOutPayrollBridge && TipOutPayrollBridge.syncAfterAllocation) {
        TipOutPayrollBridge.syncAfterAllocation(
            scope.store,
            scope.startDate,
            scope.endDate
        );
        }
      } catch (error) {
        error.allocationStage = 'payroll';
        throw error;
      }
      return { successCount: dates.length, paidSkippedCount: skippedPaidCount, closedSkippedCount: skippedClosedCount };
    }

    function submitTipAllocationScope() {
      if (allocationSubmitting) return;
      var scope = Object.freeze({
        store: (document.getElementById('allocationStore').value || '').trim(),
        startDate: document.getElementById('allocationDateStart').value,
        endDate: document.getElementById('allocationDateEnd').value
      });
      var validationError = validateAllocationScope(scope);
      if (validationError) { showAllocationScopeError(validationError); return; }
      showAllocationScopeError(null);
      setAllocationSubmitting(true);
      try {
        var allocationResult = executeTipAllocationScope(scope);
        syncPageFiltersToAllocationScope(scope);
        renderDailySummaryList();
        setAllocationSubmitting(false);
        closeTipAllocationModal(true);
        showNotification('小费分配完成' + (allocationResult.paidSkippedCount ? '，已发放日期跳过 ' + allocationResult.paidSkippedCount + ' 天' : '') + (allocationResult.closedSkippedCount ? '，未营业日期跳过 ' + allocationResult.closedSkippedCount + ' 天' : ''), 'success');
      } catch (error) {
        setAllocationSubmitting(false);
        if (error && (error.allocationStage === 'write' || error.allocationStage === 'payroll')) {
          syncPageFiltersToAllocationScope(scope);
          renderDailySummaryList();
          closeTipAllocationModal(true);
          showNotification(
            error.allocationStage === 'payroll'
              ? '分配结果已保存，但薪资同步失败，请重试同步'
              : '分配未完整完成，请检查结果后重试',
            'error'
          );
          return;
        }
        showNotification(error && error.message ? error.message : '小费分配失败，请重试', 'error');
      }
    }

