    document.addEventListener('keydown', function(event) {
      if (event.key === 'Escape' && document.getElementById('allocationHoursDetailModal') && document.getElementById('allocationHoursDetailModal').classList.contains('show')) closeAllocationHoursDetail();
      var payoutModal = document.getElementById('confirmPayoutModal');
      if (payoutModal && payoutModal.classList.contains('show') && event.key === 'Escape') {
        event.preventDefault(); closeConfirmPayoutModal(); return;
      }
      var modal = document.getElementById('tipAllocationModal');
      if (!modal || !modal.classList.contains('show')) return;
      if (event.key === 'Escape') {
        event.preventDefault();
        closeTipAllocationModal();
        return;
      }
      if (event.key !== 'Tab') return;
      var focusable = Array.from(modal.querySelectorAll('button:not([disabled]), select:not([disabled]), input:not([disabled])'));
      if (!focusable.length) return;
      var first = focusable[0];
      var last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    });

