    function genDayData(dateKey, poolRules, ruleSalt) {
      if (window.TipOutDatePoolView && TipOutDatePoolView.buildDayData) {
        return TipOutDatePoolView.buildDayData(dateKey, poolRules, ruleSalt);
      }
      var parts = dateKey.split('-');
      var extra = 0;
      if (ruleSalt != null && ruleSalt !== '') {
        var rs = String(ruleSalt);
        for (var si = 0; si < rs.length; si++) extra = (extra * 31 + rs.charCodeAt(si)) % 100000;
      }
      var seed = parts.reduce(function(a, b) { return a * 31 + parseInt(b, 10); }, 0) + extra;
      var rng = seedRandom(seed);
      var dow = new Date(dateKey + 'T00:00:00').getDay();
      var wb = (dow === 5 || dow === 6) ? 1.4 : 1.0;
      var sales = +((3800 + rng() * 4400) * wb).toFixed(2);
      var tips = +((650 + rng() * 700) * wb).toFixed(2);
      var surcharge = +((120 + rng() * 180) * wb).toFixed(2);
      var manual = +((80 + rng() * 170) * wb).toFixed(2);
      var custom = 0;
      var pool = 0;
      var poolByRule = {};
      var salesCount = 0, tipsCount = 0, surchargeCount = 0;
      (poolRules || []).forEach(function(pr) {
        if (pr.type === 'sales') salesCount++;
        else if (pr.type === 'tips') tipsCount++;
        else if (pr.type === 'surcharge') surchargeCount++;
      });
      var demoEmployees = [
        { name: 'ServerA', role: 'Server', salesAmount: +(sales * 0.45).toFixed(2) },
        { name: 'BartenderB', role: 'Bartender', salesAmount: +(sales * 0.2).toFixed(2) },
        { name: 'OtherC', role: 'Cashier', salesAmount: +(sales * 0.35).toFixed(2) }
      ];
      (poolRules || []).forEach(function(pr) {
        var base = 0;
        var ruleAmt = 0;
        var rid = pr.id || pr.type;
        if (pr.type === 'personal_sales' && window.TipOutPersonalSalesDeduct && TipOutPersonalSalesDeduct.calcPersonalSalesPoolCard) {
          var card = TipOutPersonalSalesDeduct.calcPersonalSalesPoolCard(pr, demoEmployees);
          base = card.matchedSales || 0;
          ruleAmt = card.contribution || 0;
        } else {
          if (pr.type === 'sales') base = salesCount > 0 ? sales / salesCount : sales;
          else if (pr.type === 'tips') base = tipsCount > 0 ? tips / tipsCount : tips;
          else if (pr.type === 'surcharge') base = surchargeCount > 0 ? surcharge / surchargeCount : surcharge;
          else if (pr.type === 'manual') base = manual;
          else if (pr.type === 'custom') base = pr.amount != null ? pr.amount : custom;
          ruleAmt = +(base * (pr.pct != null ? pr.pct : 0) / 100).toFixed(2);
        }
        poolByRule[rid] = ruleAmt;
        pool += ruleAmt;
      });
      pool = +pool.toFixed(2);
      var poolBaseByRule = {};
      (poolRules || []).forEach(function(pr) {
        var rid = pr.id || pr.type;
        var amt = poolByRule[rid] || 0;
        var p = pr.pct != null ? pr.pct : 0;
        if (pr.type === 'personal_sales') {
          poolBaseByRule[rid] = (window.TipOutPersonalSalesDeduct && TipOutPersonalSalesDeduct.calcPersonalSalesPoolCard)
            ? (TipOutPersonalSalesDeduct.calcPersonalSalesPoolCard(pr, demoEmployees).matchedSales || 0)
            : (p > 0 ? +(amt * 100 / p).toFixed(2) : 0);
        } else {
          poolBaseByRule[rid] = p > 0 ? +(amt * 100 / p).toFixed(2) : 0;
        }
      });
      return { sales: sales, tips: tips, surcharge: surcharge, manual: manual, custom: custom, pool: pool, poolRules: poolRules, poolByRule: poolByRule, poolBaseByRule: poolBaseByRule, employeeSales: demoEmployees };
    }

