          <div class="modal-footer">
            <button type="button" id="cancelTipAllocationBtn" class="btn" data-native-onclick="closeTipAllocationModal()">取消</button>
            <button type="button" id="confirmAllocateBtn" class="btn btn-primary" data-native-onclick="submitTipAllocationScope()">分配小费</button>
          </div>
